"use client";

import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";

import { cn } from "@/lib/utils";
import { controlChecked, focusRing } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Airy docs Checkbox: a 1rem box with a 0.3125rem corner and a grey edge.
 * Checked or mixed, it fills with the same flat green as the primary button
 * and shows a white tick or dash. Base UI owns the checked state, so a
 * controlled parent passes `checked` straight through.
 */
function Checkbox({
  className,
  indeterminate,
  ...props
}: WithClassName<CheckboxPrimitive.Root.Props>) {
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      indeterminate={indeterminate}
      className={cn(
        "peer inline-flex size-4 shrink-0 items-center justify-center rounded-[0.3125rem] border border-(--control) bg-background text-primary-foreground",
        "transition-[background-color,border-color] duration-fast ease-out",
        "hover:border-primary",
        focusRing,
        "data-[disabled]:cursor-not-allowed data-[disabled]:border-(--line-strong) data-[disabled]:bg-muted data-[disabled]:text-(--foreground-disabled)",
        controlChecked,
        "data-[indeterminate]:border-primary data-[indeterminate]:bg-primary",
        "data-[disabled]:data-[indeterminate]:border-(--line-strong) data-[disabled]:data-[indeterminate]:bg-muted",
        className,
      )}
      {...props}
    >
      <CheckboxPrimitive.Indicator
        data-slot="checkbox-indicator"
        className="flex size-full items-center justify-center text-current"
      >
        {indeterminate ? (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3">
            <path d="M3.5 8h9" stroke="currentColor" strokeWidth="2.25" strokeLinecap="round" />
          </svg>
        ) : (
          <svg viewBox="0 0 16 16" fill="none" aria-hidden="true" className="size-3">
            <path
              d="M3 8.5 6.25 11.5 13 4.5"
              stroke="currentColor"
              strokeWidth="2.25"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
          </svg>
        )}
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  );
}
Checkbox.displayName = "Checkbox";

export { Checkbox };
